sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	if (isLoading || newValue === '') {
		return;
	}

	// 1. Validação prévia no Client-Side: Verifica se segue o formato aceito(ex: yyyy-MM-dd ou dd/MM/yyyy)
	var formatoIso = /^\d{4}-\d{2}-\d{2}$/;
	var formatoBr = /^\d{2}\/\d{2}\/\d{4}$/;

	if (!formatoIso.test(newValue) && !formatoBr.test(newValue)) {
		g_form.clearValue('u_data_nascimento_solicitante');
		getMessage('data_invalida_msg', function (msg) {
			g_form.showFieldMsg('u_data_nascimento_solicitante', msg, 'error', true);
		});
		return;
	}

	var ga = new GlideAjax('x_fub_fundbrad_ev.EVUtils');
	ga.addParam('sysparm_name', 'isDateGreaterThanToday');
	ga.addParam('sysparm_date', newValue);
	ga.getXMLAnswer(function (response) {

		if (response === 'true') {
			g_form.clearValue('u_data_nascimento_solicitante');
			getMessage('data_superior_msg', function (msg) {
				g_form.showFieldMsg('u_data_nascimento_solicitante', msg, 'error', true);
			});
		} else {
			g_form.hideFieldMsg('u_data_nascimento_solicitante', 'error');
		}
	});
}
